class Solution:
    def lastStoneWeightII(self, stones):
        total = sum(stones)
        best = total
        def dfs(i, s):
            nonlocal best
            if i == len(stones):
                best = min(best, abs(total - 2 * s))
                return
            dfs(i + 1, s + stones[i])
            dfs(i + 1, s)
        dfs(0, 0)
        return best

